use std::collections::BTreeSet;

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Ids already passed through in this batch. A feed can repeat an
        // entry, so the batch is de-duplicated as well as checked against
        // the store.
        let mut emitted: BTreeSet<String> = BTreeSet::new();
        let mut out: Vec<FeedItem> = Vec::with_capacity(items.len());

        for item in items {
            // `id` is a digest the parser computed, so it is safe to use as a
            // store key. An empty id cannot identify an item, so drop it.
            if item.id.is_empty() {
                continue;
            }
            if emitted.contains(&item.id) {
                continue;
            }
            if state_read::get(&item.id).is_some() {
                // This item was marked seen in an earlier run.
                continue;
            }
            emitted.insert(item.id.clone());
            out.push(item);
        }

        out
    }
}

export!(Node);
